DROP POLICY IF EXISTS "users_require_admin_write_insert" ON "rebase"."users";
CREATE POLICY "users_require_admin_write_insert" ON "rebase"."users" AS RESTRICTIVE FOR INSERT TO "public" WITH CHECK ((SELECT (rebase.uid() IS NULL) OR (string_to_array(rebase.roles(), ',') && ARRAY['admin'])));
DROP POLICY IF EXISTS "users_require_admin_write_update_ar_34881a30" ON "rebase"."users";
DROP POLICY IF EXISTS "users_require_admin_write_update" ON "rebase"."users";
CREATE POLICY "users_require_admin_write_update" ON "rebase"."users" AS RESTRICTIVE FOR UPDATE TO "public" USING ((SELECT (rebase.uid() IS NULL) OR (string_to_array(rebase.roles(), ',') && ARRAY['admin']))) WITH CHECK ((SELECT (rebase.uid() IS NULL) OR (string_to_array(rebase.roles(), ',') && ARRAY['admin'])));
DROP POLICY IF EXISTS "users_require_admin_write_delete_ar_8591c9fe" ON "rebase"."users";
DROP POLICY IF EXISTS "users_require_admin_write_delete" ON "rebase"."users";
CREATE POLICY "users_require_admin_write_delete" ON "rebase"."users" AS RESTRICTIVE FOR DELETE TO "public" USING ((SELECT (rebase.uid() IS NULL) OR (string_to_array(rebase.roles(), ',') && ARRAY['admin'])));

